<script lang="ts">
  import{enhance}from'$app/forms';import type{SubmitFunction}from'@sveltejs/kit';import{toast}from'svelte-sonner';import type{PageProps}from'./$types';import{Badge,Breadcrumb,Button,Card,ConfirmationDialog,Icon,Input,Select,i18n,tienePermiso}from'$lib';let{data}:PageProps=$props();let open=$state(false),processing=$state(false),form:HTMLFormElement,resolveSubmit:(()=>void)|null=null,rejectSubmit:((e:Error)=>void)|null=null;const types=$derived(data.catalogos?.parametros.filter((p:{codigo_grupo:string})=>p.codigo_grupo==='tipos_recordatorio')??[]),states=$derived(data.catalogos?.parametros.filter((p:{codigo_grupo:string})=>p.codigo_grupo==='estados_recordatorio')??[]);const canCreate=$derived(tienePermiso(data.usuario.permisos,'operations.reminders.create'));const date=(v:string)=>new Intl.DateTimeFormat(i18n.locale,{dateStyle:'medium',timeStyle:'short',timeZone:data.usuario.preferencias.zona_horaria}).format(new Date(v));const submit:SubmitFunction=()=>{processing=true;return async({result,update})=>{if(result.type==='success'){await update({invalidateAll:true});toast.success(i18n.t('notifications.type.success'),{description:i18n.t('operations.saved')});resolveSubmit?.();}else{const m=result.type==='failure'&&typeof result.data?.operationMessage==='string'?result.data.operationMessage:'operations.saveError';toast.error(i18n.t('notifications.type.error'),{description:i18n.t(m)});rejectSubmit?.(new Error(m));}processing=false;resolveSubmit=null;rejectSubmit=null;};};function confirm(){if(!form.reportValidity())return Promise.reject(new Error('invalid'));return new Promise<void>((r,j)=>{resolveSubmit=r;rejectSubmit=j;form.requestSubmit();});}
</script>
<Breadcrumb items={[{label:i18n.t('nav.dashboard'),href:'/dashboard'},{label:i18n.t('nav.reminders')}]}/><section class="space-y-6"><div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-[28px] font-semibold text-ink">{i18n.t('nav.reminders')}</h1><p class="mt-1.5 text-steel">{i18n.t('operations.remindersHelp')}</p></div>{#if canCreate}<Button onclick={()=>open=true}><Icon name="bell-plus" size={17}/>{i18n.t('operations.newReminder')}</Button>{/if}</div><Card padding="none">{#if data.recordatorios.length}<div class="divide-y divide-hairline">{#each data.recordatorios as reminder}<article class="grid gap-4 px-5 py-4 sm:grid-cols-[48px_minmax(0,1fr)_auto] sm:items-center"><span class="grid size-11 place-items-center rounded-xl bg-primary-soft text-primary"><Icon name="bell-ring" size={20}/></span><div><strong class="text-sm text-ink">{reminder.titulo}</strong><p class="mt-1 text-xs text-steel">{reminder.mascota.nombre} · {reminder.tipo.etiqueta}</p></div><div class="sm:text-right"><strong class="block text-sm text-ink">{date(reminder.programado_para)}</strong><Badge variant="outline-sky">{reminder.estado_recordatorio.etiqueta}</Badge></div></article>{/each}</div>{:else}<div class="grid place-items-center py-14 text-center"><Icon name="bell-off" size={32} class="text-stone"/><p class="mt-3 text-sm text-steel">{i18n.t('operations.remindersEmpty')}</p></div>{/if}</Card></section>
<ConfirmationDialog bind:open size="wide" variant="info" icon="bell-plus" title={i18n.t('operations.newReminder')} description={i18n.t('operations.reminderFormHelp')} confirmLabel={i18n.t('operations.save')} cancelLabel={i18n.t('attentions.cancel')} confirmDisabled={processing} onConfirm={confirm}><form bind:this={form} method="POST" action="?/create" use:enhance={submit} class="grid gap-4 text-left sm:grid-cols-2"><Select name="fid_mascotas" label={i18n.t('pets.title')} required><option value="">{i18n.t('forms.select')}</option>{#each data.catalogos?.mascotas??[] as item}<option value={item.id_mascotas}>{item.nombre}</option>{/each}</Select><Select name="fid_parametros_tipo" label={i18n.t('operations.type')} required><option value="">{i18n.t('forms.select')}</option>{#each types as item}<option value={item.id_parametros}>{item.etiqueta}</option>{/each}</Select><Select name="fid_parametros_estado" label={i18n.t('operations.status')} required><option value="">{i18n.t('forms.select')}</option>{#each states as item}<option value={item.id_parametros}>{item.etiqueta}</option>{/each}</Select><Input name="programado_para" label={i18n.t('operations.scheduledAt')} type="datetime-local" required/><Input name="titulo" label={i18n.t('operations.title')} required minlength="2" maxlength="160"/><Input name="detalle" label={i18n.t('operations.detail')} maxlength="500"/></form></ConfirmationDialog>
